        end: />\]/,
        relevance: 2,
        contains: [QUOTED_IDENTIFIER,
        // can contain any constant value
        TRIPLE_QUOTED_STRING, VERBATIM_STRING, QUOTED_STRING, CHAR_LITERAL, NUMBER]
